SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(3*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");
R:=PolynomialRing(Integers());fp:=FrobeniusPolynomial(JH(84,[43]),5);assert Degree(fp) eq 122;tr:=[];closed:=[];
for n in [1..10] do z:=-n*Coefficient(fp,122-n);for j in [1..n-1] do z-:=Coefficient(fp,122-j)*tr[n-j];end for;Append(~tr,Integers()!z);num:=5^n+1-z;for k in Divisors(n) do if k lt n then num-:=k*closed[k];end if;end for;assert num mod n eq 0;Append(~closed,Integers()!(num div n));end for;
cusps:=[1:i in [1..18]] cat [2:i in [1..9]] cat [3:i in [1..6]] cat [6:i in [1..3]];nc:=[closed[d]-#[x:x in cusps|x eq d]:d in [1..10]];assert nc eq [0,0,0,126,648,2080,11376,48816,211776,983196];old:=eval Read("work/deg10/next_cases_20261030/C242/source_frobenius_degree9.m");assert Coefficients(fp) eq old[1] and cusps eq old[2];Write("work/deg10/next_cases_20261030/C242/frobenius.m",Sprint([*Coefficients(fp),cusps,nc*]):Overwrite:=true);print "C242_FRESH_FROBENIUS_COMPLETE",nc,Cputime(tt);quit;
